class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1
        for _ in range(n):
            nd = [0] * (x + 1)
            for s in range(1, x + 1):
                nd[s] = (dp[s] * s + dp[s - 1]) % MOD
            dp = nd
        N = max(n, x) + 1
        fact = [1] * N
        for i in range(1, N):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * N
        inv_fact[N - 1] = pow(fact[N - 1], MOD - 2, MOD)
        for i in range(N - 1, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD
        def C(a, b):
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD
        ans = 0
        yp = 1
        for s in range(1, min(n, x) + 1):
            yp = yp * y % MOD
            ans = (ans + C(x, s) * dp[s] % MOD * fact[s] % MOD * yp) % MOD
        return ans

