class Solution {
public:
    int numberOfWays(int n, int x, int y) {
        const long long MOD = 1e9 + 7;
        vector<long long> dp(x + 1, 0);
        dp[0] = 1;
        for (int i = 0; i < n; i++) {
            vector<long long> nd(x + 1, 0);
            for (int s = 1; s <= x; s++)
                nd[s] = (dp[s] * s + dp[s - 1]) % MOD;
            dp = nd;
        }
        int N = max(n, x) + 1;
        vector<long long> fact(N), inv(N);
        fact[0] = 1;
        for (int i = 1; i < N; i++) fact[i] = fact[i - 1] * i % MOD;
        inv[N - 1] = 1;
        long long base = fact[N - 1], r = 1, e = MOD - 2;
        while (e) { if (e & 1) r = r * base % MOD; base = base * base % MOD; e >>= 1; }
        inv[N - 1] = r;
        for (int i = N - 1; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
        auto C = [&](int a, int b) { return fact[a] * inv[b] % MOD * inv[a - b] % MOD; };
        long long ans = 0, yp = 1;
        for (int s = 1; s <= min(n, x); s++) {
            yp = yp * y % MOD;
            ans = (ans + C(x, s) * dp[s] % MOD * fact[s] % MOD * yp) % MOD;
        }
        return (int)ans;
    }
};

