class Solution {
    public int numberOfWays(int n, int x, int y) {
        final long MOD = 1_000_000_007L;
        long[] dp = new long[x + 1];
        dp[0] = 1;
        for (int i = 0; i < n; i++) {
            long[] nd = new long[x + 1];
            for (int s = 1; s <= x; s++)
                nd[s] = (dp[s] * s + dp[s - 1]) % MOD;
            dp = nd;
        }
        int N = Math.max(n, x) + 1;
        long[] fact = new long[N], inv = new long[N];
        fact[0] = 1;
        for (int i = 1; i < N; i++) fact[i] = fact[i - 1] * i % MOD;
        inv[N - 1] = pow(fact[N - 1], MOD - 2, MOD);
        for (int i = N - 1; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
        long ans = 0, yp = 1;
        for (int s = 1; s <= Math.min(n, x); s++) {
            yp = yp * y % MOD;
            long c = fact[x] * inv[s] % MOD * inv[x - s] % MOD;
            ans = (ans + c * dp[s] % MOD * fact[s] % MOD * yp) % MOD;
        }
        return (int) ans;
    }
    private long pow(long b, long e, long m) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return r;
    }
}

